    private void btnGuardarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnGuardarActionPerformed
        if (!validarCampos()) {
    return;
}

Empleado empleado = obtenerEmpleado();
EmpleadoDAO dao = new EmpleadoDAO();

if (dao.insertar(empleado)) {

    JOptionPane.showMessageDialog(this,
            "Empleado registrado correctamente.");

    cargarEmpleados();
    limpiarCampos();

} else {

    JOptionPane.showMessageDialog(this,
            "No se pudo registrar el empleado.");
}
    }//GEN-LAST:event_btnGuardarActionPerformed

    private void btnEditarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnEditarActionPerformed
        if (txtIdEmpleado.getText().trim().isEmpty()) {
    JOptionPane.showMessageDialog(this,
            "Seleccione un empleado de la tabla.");
    return;
}

if (!validarCampos()) {
    return;
}

Empleado empleado = obtenerEmpleado();

empleado.setIdEmpleado(
        Integer.parseInt(txtIdEmpleado.getText())
);

EmpleadoDAO dao = new EmpleadoDAO();

if (dao.actualizar(empleado)) {

    JOptionPane.showMessageDialog(this,
            "Empleado actualizado correctamente.");

    cargarEmpleados();
    limpiarCampos();

} else {

    JOptionPane.showMessageDialog(this,
            "No se pudo actualizar el empleado.");
}
    }//GEN-LAST:event_btnEditarActionPerformed

    private void btnEliminarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnEliminarActionPerformed
        if (txtIdEmpleado.getText().trim().isEmpty()) {

    JOptionPane.showMessageDialog(this,
            "Seleccione un empleado de la tabla.");
    return;
}

int confirmacion = JOptionPane.showConfirmDialog(
        this,
        "¿Está seguro de eliminar este empleado?",
        "Confirmar eliminación",
        JOptionPane.YES_NO_OPTION
);

if (confirmacion != JOptionPane.YES_OPTION) {
    return;
}

int idEmpleado =
        Integer.parseInt(txtIdEmpleado.getText());

EmpleadoDAO dao = new EmpleadoDAO();

if (dao.eliminar(idEmpleado)) {

    JOptionPane.showMessageDialog(this,
            "Empleado eliminado correctamente.");

    cargarEmpleados();
    limpiarCampos();

} else {

    JOptionPane.showMessageDialog(this,
            "No se pudo eliminar el empleado.");
}
    }//GEN-LAST:event_btnEliminarActionPerformed

    private void btnLimpiarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLimpiarActionPerformed
        limpiarCampos();
    }//GEN-LAST:event_btnLimpiarActionPerformed

    private void btnVolverActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnVolverActionPerformed
        java.awt.Container contenedor = getParent();

if (contenedor != null) {
    contenedor.removeAll();
    contenedor.revalidate();
    contenedor.repaint();
}
    }//GEN-LAST:event_btnVolverActionPerformed

    private void tblEmpleadosMouseClicked(java.awt.event.MouseEvent evt) {//GEN-FIRST:event_tblEmpleadosMouseClicked
        int fila = tblEmpleados.getSelectedRow();

if (fila == -1) {
    return;
}

int filaModelo = tblEmpleados.convertRowIndexToModel(fila);

txtIdEmpleado.setText(
        modeloTabla.getValueAt(filaModelo, 0).toString()
);

txtNombre.setText(
        modeloTabla.getValueAt(filaModelo, 1).toString()
);

Object telefono = modeloTabla.getValueAt(filaModelo, 2);
Object correo = modeloTabla.getValueAt(filaModelo, 3);

txtTelefono.setText(
        telefono == null ? "" : telefono.toString()
);

txtCorreo.setText(
        correo == null ? "" : correo.toString()
);

txtPuesto.setText(
        modeloTabla.getValueAt(filaModelo, 4).toString()
);
    }//GEN-LAST:event_tblEmpleadosMouseClicked

private DefaultTableModel modeloTabla;

private void configurarTabla() {

    modeloTabla = new DefaultTableModel(
            new Object[]{
                "ID", "Nombre", "Teléfono", "Correo", "Puesto"
            }, 0) {

        @Override
        public boolean isCellEditable(int fila, int columna) {
            return false;
        }
    };

    tblEmpleados.setModel(modeloTabla);
    tblEmpleados.setSelectionMode(
            javax.swing.ListSelectionModel.SINGLE_SELECTION
    );
}

private void cargarEmpleados() {

    modeloTabla.setRowCount(0);

    EmpleadoDAO dao = new EmpleadoDAO();
    List<Empleado> empleados = dao.listar();

    for (Empleado empleado : empleados) {

        modeloTabla.addRow(new Object[]{
            empleado.getIdEmpleado(),
            empleado.getNombre(),
            empleado.getTelefono(),
            empleado.getCorreo(),
            empleado.getPuesto()
        });
    }
}

private void limpiarCampos() {

    txtIdEmpleado.setText("");
    txtNombre.setText("");
    txtTelefono.setText("");
    txtCorreo.setText("");
    txtPuesto.setText("");

    tblEmpleados.clearSelection();
    txtNombre.requestFocus();
}

private boolean validarCampos() {

    if (txtNombre.getText().trim().isEmpty()
            || txtPuesto.getText().trim().isEmpty()) {

        JOptionPane.showMessageDialog(this,
                "El nombre y el puesto son obligatorios.");
        return false;
    }

    if (txtNombre.getText().trim().length() > 150
            || txtTelefono.getText().trim().length() > 20
            || txtCorreo.getText().trim().length() > 100
            || txtPuesto.getText().trim().length() > 100) {

        JOptionPane.showMessageDialog(this,
                "Uno de los campos supera la longitud permitida.");
        return false;
    }

    return true;
}

private Empleado obtenerEmpleado() {

    Empleado empleado = new Empleado();

    empleado.setNombre(txtNombre.getText().trim());
    empleado.setTelefono(txtTelefono.getText().trim());
    empleado.setCorreo(txtCorreo.getText().trim());
    empleado.setPuesto(txtPuesto.getText().trim());

    return empleado;
}


